use std::path::Path;use artifactum_core::{AcquireContext,Acquisition,AcquisitionPlan,ArtifactProvider,ArtifactRequirement,ProviderCapabilities,ProviderDescriptor,ResolveContext,Resolution,ResolvedFile};use artifactum_provider_command::{find_and_copy,required_fragment,run_checked,single_file_resolution,source_with,string_field,tempdir};use async_trait::async_trait;
#[derive(Clone,Debug,Default)]pub struct WandbProvider;
#[async_trait]impl ArtifactProvider for WandbProvider{fn descriptor(&self)->ProviderDescriptor{ProviderDescriptor{name:"wandb".into(),version:env!("CARGO_PKG_VERSION").into(),schemes:vec!["wandb".into()],capabilities:ProviderCapabilities{resolve:true,acquire:true,auth:true,..Default::default()},metadata:Default::default()}}async fn resolve(&self,r:&ArtifactRequirement,_:&ResolveContext)->artifactum_core::Result<Resolution>{let(root,path)=required_fragment("wandb",r.reference.locator(),"path")?;single_file_resolution("wandb",format!("wandb:{root}#{path}"),r,path,source_with([("artifact",root.into()),("path",path.into())]))}async fn prepare_acquisition(&self,f:&ResolvedFile,_:&AcquireContext)->artifactum_core::Result<AcquisitionPlan>{Ok(AcquisitionPlan::ProviderManaged{state:f.source.clone()})}async fn acquire_managed(&self,f:&ResolvedFile,_:&AcquisitionPlan,d:&Path,_:&AcquireContext)->artifactum_core::Result<Acquisition>{let artifact=string_field(&f.source,"artifact","wandb")?;let path=string_field(&f.source,"path","wandb")?;let tmp=tempdir("wandb")?;run_checked("wandb","wandb",["artifact","get","--root",tmp.path().to_str().unwrap_or("."),artifact]).await?;let n=find_and_copy(tmp.path(),path,d,"wandb").await?;Ok(Acquisition{bytes_written:Some(n),metadata:Default::default()})}}
pub fn provider()->WandbProvider{WandbProvider}
